export type IconName = keyof typeof icons

export function isIconName(name: string | undefined): name is IconName {
  return !!name && name in icons
}

export interface IconProps extends ComponentProps<"svg"> {
  name: IconName
  size?: "small" | "normal" | "medium" | "large"
}

export function Icon(props: IconProps) {
  const [local, others] = splitProps(props, ["name", "size", "class", "classList"])
  const viewBox = () =>
    local.name === "magnifying-glass" || local.name === "arrow-undo-down" || local.name === "filter-funnel"
      ? "0 0 16 16"
      : local.name === "refresh-cw" || local.name === "auto-wrap" || local.name === "globe"
        ? "0 0 24 24"
        : local.name === "folder-iocn"
          ? "0 0 1228 1024"
          : local.name === "review" ||
              local.name === "review-active" ||
              local.name === "shortcut-search-icon" ||
              local.name === "webpage-icon" ||
              local.name === "file1-icon" ||
              local.name === "diff-summary-header" ||
              local.name === "arrow-uturn-down-filled" ||
              local.name === "terminal-command" ||
              local.name === "edit-file" ||
              local.name === "right-link" ||
              local.name === "refresh-browse" ||
              local.name === "git-branch-filled" ||
              local.name === "git-branch-filled2" ||
              local.name === "branch-icon" ||
              local.name === "json-icon" ||
              local.name === "html-icon" ||
              local.name === "python-icon" ||
              local.name === "files-icon"
            ? "0 0 1024 1024"
            : "0 0 20 20"
  return (
    <div data-component="icon" data-size={local.size || "normal"} class={local.class} classList={local.classList}>
      <svg
        data-slot="icon-svg"
        fill="none"
        viewBox={viewBox()}
        preserveAspectRatio="xMidYMid meet"
        innerHTML={icons[local.name as keyof typeof icons]}
        aria-hidden="true"
        {...others}
      />
    </div>
  )
}
